// Regenerates src/core/okf-viz/assets.ts from the vendored viewer files
// (viz.html, viz.js, viz.css). The assets are embedded as string constants so
// the Next standalone build needs no runtime file reads.
//   node scripts/gen-okf-viz-assets.mjs
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "src", "core", "okf-viz");
const names = [
	["VIZ_HTML", "viz.html"],
	["VIZ_JS", "viz.js"],
	["VIZ_CSS", "viz.css"],
];
let out =
	"// GENERATED by scripts/gen-okf-viz-assets.mjs from the vendored files next to it\n" +
	"// (Apache-2.0, Copyright 2026 Google LLC - see NOTICE). Do not edit by hand.\n\n";
for (const [name, file] of names) {
	out += `export const ${name} = ${JSON.stringify(fs.readFileSync(path.join(dir, file), "utf-8"))};\n\n`;
}
fs.writeFileSync(path.join(dir, "assets.ts"), out.trimEnd() + "\n");
